inline const MOR *GetMOR(const void *buf) {
  return ::flatbuffers::GetRoot<MOR>(buf);
}

inline const MOR *GetSizePrefixedMOR(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<MOR>(buf);
}

inline const char *MORIdentifier() {
  return "$MOR";
}

inline bool MORBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, MORIdentifier());
}

inline bool SizePrefixedMORBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, MORIdentifier(), true);
}

template <bool B = false>
inline bool VerifyMORBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<MOR>(MORIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedMORBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<MOR>(MORIdentifier());
}

inline void FinishMORBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<MOR> root) {
  fbb.Finish(root, MORIdentifier());
}

inline void FinishSizePrefixedMORBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<MOR> root) {
  fbb.FinishSizePrefixed(root, MORIdentifier());
}

